SELECT wc.id      AS work_case_id,
       wc.status  AS status,
       wc.starts_at,
       wc.ends_at,
       CASE WHEN wc.status = 'READY' THEN 'CHECK_IN' ELSE 'CHECK_OUT' END AS scan_type
FROM work_cases wc
WHERE wc.worker_id = #{workerId}
  AND wc.workplace_id = #{workplaceId}
  AND (
      (
          wc.status = 'READY'
          AND wc.starts_at <= #{readyLatestStartsAt}
          AND wc.starts_at > #{readyEarliestStartsAt}
      )
      OR (
          wc.status = 'IN_PROGRESS'
          AND wc.ends_at > #{checkOutEarliestEndsAt}
          AND EXISTS (
              SELECT 1
              FROM attendance_records ar
              WHERE ar.work_case_id = wc.id
                AND ar.attendance_type = 'CHECK_IN'
                AND ar.result = 'SUCCESS'
          )
      )
  )
ORDER BY wc.starts_at, wc.id
LIMIT 2

SELECT COUNT(*)
FROM (
    SELECT wc.id
    FROM work_cases wc
    WHERE wc.worker_id = #{workerId}
      AND wc.workplace_id = #{workplaceId}
      AND wc.status = 'COMPLETED'
      AND wc.starts_at <= #{readyLatestStartsAt}
      AND wc.ends_at > #{checkOutEarliestEndsAt}
    LIMIT 2
) completed

