INSERT INTO attendance_records (
    work_case_id, worker_id, qr_token_id, attendance_type,
    captured_at, attempted_at, distance_meters, accuracy_meters,
    result, failure_reason, early_checkout_confirmed_at
) VALUES (
    #{workCaseId}, #{workerId}, #{qrTokenId}, #{attendanceType},
    #{capturedAt}, #{attemptedAt}, #{distanceMeters}, #{accuracyMeters},
    #{result}, #{failureReason}, #{earlyCheckoutConfirmedAt}
)
